function startBExercise(id){
  currentB=B_EXERCISES.find(x=>x.id===id);
  if(!currentB) return;
  bStepIndex=-1;
  bPredictionSatisfied=true;
  lastBState={};

  document.getElementById('bSelect').classList.add('hidden');
  document.getElementById('bLab').classList.add('show');
  document.getElementById('bComplete').classList.remove('show');
  document.getElementById('bLabTitle').textContent=currentB.title;
  document.getElementById('bLabMeta').textContent=`科目B・${currentB.concept}・${currentB.level}`;
  document.getElementById('bCode').innerHTML=currentB.code.map((line,i)=>`<div class="b-code-line" data-bline="${i}">${escapeHtml(line)}</div>`).join('');
  resetBView();
}

