functionSources.renderBStep:
function renderBStep(step){
  document.querySelectorAll('.b-code-line').forEach(l=>l.classList.remove('active'));
  const active=document.querySelector(`.b-code-line[data-bline="${step.line}"]`);
  if(active) active.classList.add('active');

  renderBState(step.state||{});
  renderBVisual(step);
  document.getElementById('bTraceMessage').textContent=step.msg||'';
  document.getElementById('bTraceProgress').style.width=`${((bStepIndex+1)/currentB.steps.length)*100}%`;

  if(step.predict){
    showBPrediction(step.predict);
  }else{
    bPredictionSatisfied=true;
    document.getElementById('predictionBox').classList.remove('show');
  }

  if(bStepIndex===currentB.steps.length-1 && !step.predict){
    finishBExercise();
  }
}

functionSources.renderBGrid:
function renderBGrid(){
  const root=document.getElementById('bExerciseGrid');
  if(!root) return;
  root.innerHTML='';
  const done=B_EXERCISES.filter(ex=>(profile.bProgress?.[ex.id]||0)>=100).length;
  const visible=B_EXERCISES.filter(ex=>currentBFilter==='all'||ex.level===currentBFilter);
  visible.forEach(ex=>{
    const pct=profile.bProgress?.[ex.id]||0;
    const card=document.createElement('div');
    const nextId=traceNextRecommendation()?.id;
    card.className='b-card'+(pct>=100?' done':'')+(ex.id===nextId?' b-next-highlight':'');
    const diffClass=ex.level==='標準'?'medium':ex.level==='応用'?'hard':'';
    card.innerHTML=`
      <div class="b-card-top">
        <div class="b-card-icon">${ex.icon}</div>
        <div>
          <div class="b-card-title">${ex.title}</div>
          <div class="b-card-meta">${ex.concept}</div>
        </div>
      </div>
      <div class="b-card-desc">${ex.desc}</div>
      <div class="b-card-bottom">
        <span class="difficulty ${diffClass}">${ex.level}</span>
        ${pct>=100?'<span class="b-check">✓ 完了</span>':''}
        <button class="b-start" data-bex="${ex.id}">${pct>=100?'もう一度':'開始'}</button>
      </div>`;
    root.appendChild(card);
  });
  const t=document.getElementById('bProgressText');
  if(t){
    const levels=['基礎','標準','応用'].map(level=>{
      const all=B_EXERCISES.filter(x=>x.level===level).length;
      const clear=B_EXERCISES.filter(x=>x.level===level&&(profile.bProgress?.[x.id]||0)>=100).length;
      return `${level}${clear}/${all}`;
    }).join(' ・ ');
    t.innerHTML=`<div>${done} / ${B_EXERCISES.length}</div><div style="font-size:14px;color:#8965ab;margin-top:2px">${levels}</div>`;
  }
  root.querySelectorAll('[data-bex]').forEach(b=>b.onclick=()=>startBExercise(b.dataset.bex));
  renderTraceNextCard();
  if(typeof renderSubjectBHub==='function')renderSubjectBHub();
}
